command_rows.command:
/bin/bash -lc "python3 - <<'PY'
import os
for p in ['reports/inventory-summary.txt','data/stock.csv','tools/make_inventory.py']:
    print(f'[{p}]')
    try:
        names=os.listxattr(p)
        print('xattrs:', names)
        for n in names:
            try: print(n, repr(os.getxattr(p,n)))
            except OSError as e: print(n, e)
    except OSError as e: print(e)
PY
printf '%s\\n' '[environment names]' && env | cut -d= -f1 | sort
printf '%s\\n' '[processes]' && ps -eo user,pid,ppid,lstart,args --forest
printf '%s\\n' '[whyfs paths]' && find /run /var/tmp /tmp /opt /usr/local /etc -maxdepth 5 -iname '*whyfs*' -o -iname '*provenance*' 2>/dev/null | sort"

